mapper.select:
SELECT NVL(SUM( (TO_NUMBER(SUBSTR(END_TM, 1, 2)) * 60 + TO_NUMBER(SUBSTR(END_TM, 3, 2)))
              - (TO_NUMBER(SUBSTR(BEGIN_TM, 1, 2)) * 60 + TO_NUMBER(SUBSTR(BEGIN_TM, 3, 2))) ), 0)
  FROM TB_RESVE
 WHERE MBER_ID = #{mberId}
   AND RESVE_DE = #{resveDe}
   AND RESVE_STTUS_CD IN ('01', '02')

SELECT RESVE_SN, BEGIN_TM, END_TM, RESVE_STTUS_CD
  FROM TB_RESVE
 WHERE FCLTY_SN = #{fcltySn}
   AND RESVE_DE = #{resveDe}
   AND RESVE_STTUS_CD IN ('01', '02')
 ORDER BY BEGIN_TM

SELECT * FROM (
	SELECT 

	 WHERE R.MBER_ID = #{mberId}
	   AND R.RESVE_DE >= #{today}
	   AND R.RESVE_STTUS_CD IN ('01', '02')
	 ORDER BY R.RESVE_DE, R.BEGIN_TM
) WHERE ROWNUM <= 3

SELECT * FROM (
	SELECT 

	 WHERE R.RESVE_STTUS_CD = '01'
	   AND R.RESVE_DE >= #{today}
	 ORDER BY R.REGIST_DT, R.RESVE_SN
) WHERE ROWNUM <= #{count}
